// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(address caller, uint256 newAmount) public {
        vm.assume(caller != address(this));
        uint256 beforeVal = c.winnersPerPeriod();
        vm.prank(caller);
        try c.updateWinnersPerPeriod(newAmount) {} catch {}
        if (c.isAdmin(caller)) {
            assertTrue(true);
            return;
        }
        uint256 afterVal = c.winnersPerPeriod();
        assertTrue(afterVal == beforeVal);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(address caller, uint256 newValue) public {
        vm.assume(caller != address(this));
        uint256 oldValue = c.winnersPerPeriod();
        vm.prank(caller);
        c.updateWinnersPerPeriod(newValue);
        if (caller == address(this)) {
            assertEq(c.winnersPerPeriod(), newValue);
        } else {
            assertEq(c.winnersPerPeriod(), oldValue);
        }
    }
}

