pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(address caller, uint256 newValue) public {
        vm.assume(caller != address(this));
        vm.assume(!c.isAdmin(caller));
        vm.prank(caller);
        bool ok;
        try c.updateWinnersPerPeriod(newValue) { ok = true; } catch { ok = false; }
        assertTrue(!ok, "non-admin should revert");
    }
}
